import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../models/zaylo_models.dart';import '../../repositories/providers.dart';
class ExpensesScreen extends ConsumerWidget{const ExpensesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final items=ref.watch(expensesProvider);final spent=items.where((e)=>e.type==ExpenseType.expense).fold<double>(0,(a,b)=>a+b.amount);return Scaffold(appBar:AppBar(title:const Text('Expense Tracker')),floatingActionButton:FloatingActionButton.extended(key:const Key('addExpenseFab'),onPressed:()=>_add(context,ref),label:const Text('Add'),icon:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[SegmentedButton(segments:const [ButtonSegment(value:'day',label:Text('Day')),ButtonSegment(value:'week',label:Text('Week')),ButtonSegment(value:'month',label:Text('Month'))],selected:const {'week'},onSelectionChanged:(_){ }),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('Total spending: \$${spent.toStringAsFixed(2)}'),const Text('Remaining budget: \$230.00'),LinearProgressIndicator(value:(spent/300).clamp(0,1))]))),for(final e in items) ListTile(title:Text(e.title),subtitle:Text(e.category),trailing:Text('${e.type==ExpenseType.expense?'-':'+'}\$${e.amount}'))]));}void _add(BuildContext context,WidgetRef ref){final title=TextEditingController();final amount=TextEditingController();showModalBottomSheet(context:context,isScrollControlled:true,builder:(context)=>Padding(padding:EdgeInsets.only(left:16,right:16,top:16,bottom:MediaQuery.of(context).viewInsets.bottom+16),child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(key:const Key('expenseTitleField'),controller:title,decoration:const InputDecoration(labelText:'Expense title')),TextField(key:const Key('expenseAmountField'),controller:amount,decoration:const InputDecoration(labelText:'Amount'),keyboardType:TextInputType.number),ElevatedButton(key:const Key('saveExpenseButton'),onPressed:(){ref.read(expensesProvider.notifier).add(ExpenseTransaction(title:title.text.isEmpty?'New expense':title.text,amount:double.tryParse(amount.text)??0,category:'Other',type:ExpenseType.expense,date:DateTime.now()));Navigator.pop(context);},child:const Text('Save expense'))])));}}
